from datetime import timedelta

import config
import database
import rankings
import support


class RankingsTests(support.DatabaseCase):
    """Use two occurrences per series to distinguish aggregate series from individual events."""

    def setUp(self):
        """Create a tiny hand-calculated fixture with attended, unrated and cancelled rows."""
        super().setUp()
        self.users = [database.create_user(self.connection, name, is_synthetic=index > 0,
                                           now=support.NOW)
                      for index, name in enumerate(('Alex', 'Lena', 'Noah', 'Mia'))]
        self.user = self.users[0]
        records = []
        for name in ('Alpha', 'Bravo', 'Charlie'):
            for offset in (3, 2):
                start = support.NOW - timedelta(days=offset)
                records.append(support.record(external_id=name, title=name, start=start,
                                               end=start + timedelta(hours=1)))
        self.save(records, include_past=True, is_placeholder=True)
        with self.connection:
            self.connection.execute('''UPDATE series SET bundle_id=
                (SELECT id FROM bundles WHERE key=?) WHERE title=?''', ('leisure_games', 'Bravo'))
            self.connection.execute('''UPDATE series SET bundle_id=
                (SELECT id FROM bundles WHERE key=?) WHERE title=?''', ('sports_ball', 'Charlie'))
        self.add('Alpha', 0, 0, 'attended', 5)
        self.add('Alpha', 1, 0, 'attended', 3, demo=True)
        self.add('Alpha', 0, 1, 'attended', 4)
        self.add('Alpha', 1, 1, 'attended')
        self.add('Alpha', 0, 2, 'confirmed')
        self.add('Alpha', 1, 2, 'not_attended')
        self.add('Alpha', 0, 3, 'cancelled')
        self.add('Bravo', 0, 0, 'attended', 5)
        self.add('Bravo', 0, 1, 'attended', 5)
        self.add('Bravo', 1, 1, 'confirmed')
        self.add('Charlie', 0, 0, 'not_attended')
        self.add('Charlie', 1, 0, 'cancelled')
        for index in (1, 2, 3):
            self.add('Charlie', 0, index, 'attended', 3)

    def add(self, title, occurrence, person, status, rating=None, demo=False):
        """Insert an isolated fixture interaction; production writes use the state machine."""
        event_id = self.connection.execute('''SELECT e.id FROM events e
            JOIN series s ON s.id=e.series_id WHERE s.title=? ORDER BY e.start_time LIMIT 1 OFFSET ?
        ''', (title, occurrence)).fetchone()[0]
        with self.connection:
            self.connection.execute('''INSERT INTO interactions
                (user_id,event_id,status,rating,confirmed_at,answered_at,is_demo)
                VALUES (?,?,?,?,?,?,?)''', (self.users[person], event_id, status, rating,
                                            database.to_db_text(support.NOW - timedelta(days=5)),
                                            database.to_db_text(support.NOW), int(demo)))

    def test_each_metric_orders_series_and_excludes_cancelled(self):
        """Aggregate multiple dates and apply each metric's different attendance semantics."""
        expected = {'popular': (['Alpha', 'Charlie', 'Bravo'], [6, 4, 3]),
                    'attended': (['Alpha', 'Charlie', 'Bravo'], [4, 3, 2]),
                    'best_rated': (['Alpha', 'Charlie'], [4, 3]),
                    'feedbacked': (['Alpha', 'Charlie', 'Bravo'], [3, 3, 2])}
        for metric, (titles, values) in expected.items():
            with self.subTest(metric=metric):
                frame = rankings.get_ranking(self.connection, metric, 'all', self.user)
                self.assertEqual(list(frame['title']), titles)
                self.assertEqual(list(frame['value']), values)
                columns = ['title', 'organizer', 'direction_key', 'bundle_name', 'value', 'n']
                self.assertEqual(list(frame.columns), columns)

    def test_you_scope_and_rating_minima(self):
        """One local rating qualifies while two global ratings do not reach the global minimum."""
        frame = rankings.get_ranking(self.connection, 'best_rated', 'you', self.user)
        self.assertEqual(list(frame['title']), ['Bravo', 'Alpha'])
        self.assertEqual(list(frame['n']), [1, 2])
        self.assertEqual(list(frame['value']), [5, 4])
        for metric, values in [('popular', [2, 1, 1]), ('attended', [2, 1]),
                               ('feedbacked', [2, 1])]:
            frame = rankings.get_ranking(self.connection, metric, 'you', self.user)
            self.assertEqual(list(frame['value']), values)

    def test_category_filters_limits_and_bound_sql_values(self):
        """Filter direction/bundle jointly, cap results and keep malicious text out of SQL."""
        for direction, bundle in [('leisure', None), (None, 'leisure_games'),
                                   ('leisure', 'leisure_games')]:
            frame = rankings.get_ranking(self.connection, 'popular', 'all', None, direction, bundle)
            self.assertEqual(list(frame['title']), ['Bravo'])
        frame = rankings.get_ranking(self.connection, 'popular', 'all', None, top_n=1)
        self.assertEqual(list(frame['title']), ['Alpha'])
        for direction, bundle in [('career', 'leisure_games'), ("' OR 1=1 --", None)]:
            frame = rankings.get_ranking(self.connection, 'popular', 'all', None, direction, bundle)
            self.assertTrue(frame.empty)

    def test_invalid_ranking_requests(self):
        """Reject unknown metrics/scopes and invalid limits without issuing a query."""
        for metric, scope, uid, limit in [('bad', 'all', None, 10), ('popular', 'bad', 1, 10),
                                           ('popular', 'you', None, 10),
                                           ('popular', 'you', True, 10),
                                           ('popular', 'all', None, 0),
                                           ('popular', 'all', None, 2.5)]:
            with self.assertRaises(ValueError):
                rankings.get_ranking(self.connection, metric, scope, uid, top_n=limit)

    def test_category_overview_counts_only_current_plans(self):
        """Include zero-count directions and average stars without treating missing as zero."""
        frame = rankings.category_overview(self.connection, self.user).set_index('direction_key')
        self.assertEqual(frame['you_confirmed'].sum(), 0)
        self.assertEqual(frame.loc['career', 'all_confirmed'], 1)
        self.assertEqual(frame.loc['leisure', 'all_confirmed'], 1)
        self.assertEqual(frame.loc['sports', 'all_confirmed'], 0)
        self.assertAlmostEqual(frame.loc['career', 'you_avg_rating'], 4)
        self.assertAlmostEqual(frame.loc['sports', 'all_avg_rating'], 3)
        self.assertTrue(rankings.pd.isna(frame.loc['sports', 'you_avg_rating']))

    def test_empty_rankings_and_chart_values(self):
        """Render detached Figures with matching bar values, direction colours and zero data."""
        frame = rankings.get_ranking(self.connection, 'popular', 'all', None)
        fig = rankings.plot_ranking(frame, 'Most popular')
        self.assertEqual([bar.get_width() for bar in fig.axes[0].patches], [6, 4, 3])
        self.assertTrue(fig.axes[0].yaxis_inverted())
        self.assertEqual(fig.axes[0].get_title(), 'Most popular')
        fig.savefig(self.directory / 'ranking.png')
        before = rankings.plt.get_fignums()
        database.reset_database(self.connection)
        empty = rankings.get_ranking(self.connection, 'popular', 'all', None)
        self.assertTrue(empty.empty)
        rankings.plot_ranking(empty, config.RANKING_EMPTY_MESSAGE)
        rankings.plot_category_overview(rankings.category_overview(self.connection, self.user))
        self.assertEqual(rankings.plt.get_fignums(), before)

    def test_data_source_and_training_summaries(self):
        """Count series without occurrence multiplication and separate eligible training origins."""
        counts = database.get_source_counts_df(self.connection).iloc[0]
        self.assertEqual((counts['series'], counts['occurrences'], counts['placeholder_series']),
                         (3, 6, 3))
        self.assertEqual(database.get_training_summary(self.connection, support.NOW),
                         {'Synthetic': 5, 'Demo': 1, 'Yours': 2, 'Total': 8, 'Positive': 4})
